选择排序原理：每趟从未排序部分选最小元素，放到已排序末尾。

1. 外层循环i从0到n-2，共n-1趟。

2. 内层循环找i到n-1中最小元素下标min_idx。

3. 交换arr[i]和arr[min_idx]。

4. 时间复杂度O(n²)，原地排序。

```cpp
#include <iostream>
using namespace std;

void selectionSort(int arr[], int n) {
    for (int i = 0; i < n-1; i++) {
        int min_idx = i;
        for (int j = i+1; j < n; j++) {
            if (arr[j] < arr[min_idx]) min_idx = j;
        }
        int temp = arr[i];
        arr[i] = arr[min_idx];
        arr[min_idx] = temp;
    }
}

void printArray(int arr[], int n) {
    for (int i = 0; i < n; i++) cout << arr[i] << " ";
    cout << endl;
}

int main() {
    int arr[] = {64,25,12,22,11};
    int n = sizeof(arr)/sizeof(arr[0]);
    cout << "排序前："; printArray(arr, n);
    selectionSort(arr, n);
    cout << "排序后："; printArray(arr, n);
    return 0;
}
```

手动模拟排序正确，每趟选最小交换，结果正确。

