冒泡排序：

1. 相邻元素比较，逆序则交换，每趟最大元素"浮"到末尾。

2. 加swapped标志，某趟无交换说明已有序，提前终止，最好情况O(n)。

3. 每趟后末尾i个元素有序，内层循环到n-1-i。

```cpp
#include <iostream>
using namespace std;

void bubbleSort(int arr[], int n) {
    for (int i = 0; i < n-1; i++) {
        bool swapped = false;
        for (int j = 0; j < n-1-i; j++) {
            if (arr[j] > arr[j+1]) {
                int temp = arr[j];
                arr[j] = arr[j+1];
                arr[j+1] = temp;
                swapped = true;
            }
        }
        if (!swapped) break;
    }
}

void printArr(int arr[], int n) {
    for (int i = 0; i < n; i++) cout << arr[i] << " ";
    cout << endl;
}

int main() {
    int arr[] = {64,34,25,12,22,11,90};
    int n = sizeof(arr)/sizeof(arr[0]);
    bubbleSort(arr, n);
    printArr(arr, n);
    return 0;
}
```

稳定排序，优化后最好情况O(n)，排序正确。

二分查找：

1. 前提数组有序。

2. 左闭右闭区间[left, right]，循环条件left<=right。

3. mid = left + (right-left)/2避免溢出。

4. arr[mid]==target找到，大于target去左半right=mid-1，小于去右半left=mid+1。

```cpp
#include <iostream>
using namespace std;

int binarySearch(int arr[], int n, int target) {
    int left = 0, right = n-1;
    while (left <= right) {
        int mid = left + (right-left)/2;
        if (arr[mid] == target) return mid;
        else if (arr[mid] > target) right = mid - 1;
        else left = mid + 1;
    }
    return -1;
}

int main() {
    int arr[] = {11,12,22,25,34,64,90};
    int n = sizeof(arr)/sizeof(arr[0]);
    cout << binarySearch(arr, n, 22) << endl;
    cout << binarySearch(arr, n, 50) << endl;
    return 0;
}
```

时间O(logn)效率高，边界处理正确，找首尾元素都正确。

