#include <iostream>
using namespace std;
const double PI = 3.14159;

class Shape {
public:
    virtual double getArea() const { return 0; }
    virtual ~Shape() {}
};

class Rectangle : public Shape {
    double w, h;
public:
    Rectangle(double a, double b) : w(a), h(b) {}
    double getArea() const override { return w*h; }
};

class Circle : public Shape {
    double r;
public:
    Circle(double a) : r(a) {}
    double getArea() const override { return PI*r*r; }
};

int main() {
    Shape* arr[] = {new Rectangle(5,3), new Circle(4)};
    for(int i=0;i<2;i++) cout << arr[i]->getArea() << endl;
    for(int i=0;i<2;i++) delete arr[i];
    return 0;
}
```

