数组实现栈：

1. 栈后进先出LIFO，top初始-1表示空。

2. push：top++后存元素，先检查是否满top>=99。

3. pop：返回arr[top--]，先检查是否空top<0。

4. peek返回栈顶不弹出，isEmpty判断top<0。

```cpp
#include <iostream>
using namespace std;
const int MAX = 100;

class Stack {
    int arr[MAX];
    int top;
public:
    Stack() : top(-1) {}
    bool push(int x) {
        if(top >= MAX-1) { cout << "栈满！" << endl; return false; }
        arr[++top] = x; return true;
    }
    int pop() {
        if(top < 0) { cout << "栈空！" << endl; return -1; }
        return arr[top--];
    }
    int peek() const {
        if(top < 0) { cout << "栈空！" << endl; return -1; }
        return arr[top];
    }
    bool isEmpty() const { return top < 0; }
};

int main() {
    Stack s;
    s.push(10); s.push(20); s.push(30);
    cout << s.pop() << endl;
    cout << s.peek() << endl;
    return 0;
}
```

