```cpp
#include <iostream>
using namespace std;
const int MAX = 100;

class Queue {
    int arr[MAX];
    int front, rear;
public:
    Queue() : front(0), rear(0) {}
    bool enqueue(int x) {
        if((rear+1)%MAX == front) { cout << "队满！" << endl; return false; }
        arr[rear] = x; rear = (rear+1)%MAX; return true;
    }
    int dequeue() {
        if(front==rear) { cout << "队空！" << endl; return -1; }
        int x = arr[front]; front = (front+1)%MAX; return x;
    }
    int getFront() const {
        if(front==rear) { cout << "队空！" << endl; return -1; }
        return arr[front];
    }
    bool isEmpty() const { return front == rear; }
};

int main() {
    Queue q;
    q.enqueue(1); q.enqueue(2); q.enqueue(3);
    cout << q.dequeue() << endl;
    cout << q.getFront() << endl;
