    for(int i=0;i<m-1;i++) day += months[i];
    cout << "第" << day << "天" << endl;
    return 0;
}
```

正确处理闰年，累加月份天数，结果正确。

菜单程序：

1. do-while循环显示菜单，直到选0退出。

2. switch处理选择，非0选项让用户输入两个数计算。

```cpp
#include <iostream>
using namespace std;

int main() {
    int choice;
    do {
        cout << "\n=====计算器=====" << endl;
        cout << "1.加法" << endl;
        cout << "2.减法" << endl;
        cout << "3.乘法" << endl;
        cout << "4.除法" << endl;
        cout << "0.退出" << endl;
        cout << "请选择：";
        cin >> choice;
        if(choice==0) break;
        double a,b;
        cout << "输入两个数：";
        cin >> a >> b;
        switch(choice) {
            case 1: cout << a+b << endl; break;
            case 2: cout << a-b << endl; break;
            case 3: cout << a*b << endl; break;
            case 4: if(b!=0) cout << a/b << endl; else cout << "除零错误" << endl; break;
            default: cout << "无效选择" << endl;
        }
    } while(choice != 0);
    cout << "程序结束" << endl;
    return 0;
}
```

循环菜单，switch处理，除法判零，退出正常。

函数重载：

1. 同名函数参数列表不同（类型、个数不同）构成重载。

2. 三个add：int加int，double加double，string加string。

```cpp
#include <iostream>
#include <string>
using namespace std;

int add(int a, int b) { return a+b; }
double add(double a, double b) { return a+b; }
string add(string a, string b) { return a+b; }

int main() {
    cout << add(1,2) << endl;
    cout << add(1.5,2.5) << endl;
    cout << add("Hello ", "World") << endl;
    return 0;
}
```

编译器根据实参类型自动调用对应函数，体现静态多态。
